INSERT INTO tef_knowledge (content, metadata) VALUES
('Règle du subjonctif : On l''utilise après "il faut que", "bien que", "pour que", "avant que". Exemple : Il faut que tu viennes.', '{"category": "grammaire", "topic": "subjonctif"}'),
('Accord du participe passé avec avoir : Le participe passé ne s''accorde jamais avec le sujet. Il s''accorde avec le COD si celui-ci est placé avant le verbe. Exemple : Les pommes que j''ai mangées.', '{"category": "grammaire", "topic": "accords"}'),
('Conseil Section A Expression Orale : Utilisez le vouvoiement. Posez au moins 10 questions pour obtenir toutes les informations. Soyez poli et terminez par "Merci beaucoup, bonne journée".', '{"category": "conseil", "topic": "EO-SectionA"}'),
('Critère B2 : Utilisation de connecteurs logiques complexes (néanmoins, toutefois, par conséquent). Richesse du vocabulaire et maîtrise des temps du passé (plus-que-parfait).', '{"category": "critère", "topic": "B2"}');
